"""Password reset flow."""

import logging
import secrets
import time
from dataclasses import dataclass

from accounts.crypto import hash_password, tokens_match

logger = logging.getLogger(__name__)

USERS: dict[str, dict] = {}

# Short enough to retype from a reset email without copy and paste.
TOKEN_BYTES = 6

# A token stops being accepted 30 minutes after it was issued.
TOKEN_TTL_SECONDS = 30 * 60


@dataclass
class IssuedToken:
    token: str
    issued_at: float


# Each request can leave more than one outstanding token per account, so tokens
# are tracked in a list rather than overwriting a single slot.
RESET_TOKENS: dict[str, list[IssuedToken]] = {}


def new_salt() -> str:
    """Return a per-user salt for password storage."""
    return secrets.token_hex(8)


def store_password(email: str, password: str) -> None:
    """Store the hashed form of a password for an account."""
    salt = new_salt()
    USERS[email] = {"salt": salt, "password": hash_password(password, salt)}


def make_token() -> str:
    """Return a reset token."""
    return secrets.token_urlsafe(TOKEN_BYTES)


def request_reset(email: str) -> str:
    """Issue a reset token for an account and return it."""
    token = make_token()
    RESET_TOKENS.setdefault(email, []).append(IssuedToken(token=token, issued_at=time.time()))
    logger.info("issued reset token %s... for %s", token[:4], email)
    return token


def _live_tokens(email: str) -> list[IssuedToken]:
    """Return the account's outstanding tokens that have not yet expired."""
    now = time.time()
    return [t for t in RESET_TOKENS.get(email, []) if now - t.issued_at <= TOKEN_TTL_SECONDS]


def check_token(email: str, token: str) -> bool:
    """Check a reset token against the issued ones."""
    return any(tokens_match(t.token, token) for t in _live_tokens(email))


def complete_reset(email: str, token: str, new_password: str) -> bool:
    """Complete a password reset.

    Returns False without raising if the token is unknown, already used, or older
    than 30 minutes. On success the new password is stored and every other
    outstanding token for the account, used or not, is discarded.
    """
    if not any(tokens_match(t.token, token) for t in _live_tokens(email)):
        return False
    store_password(email, new_password)
    del RESET_TOKENS[email]
    return True
